import sys

def main():
    data = sys.stdin.read().strip()
    if not data:
        return
    R = int(data)
    lines = []
    for i in range(1, R + 1):
        chars = [chr(ord('A') + j) for j in range(i)]
        lines.append(' '.join(chars))
    sys.stdout.write('\n'.join(lines))

if __name__ == "__main__":
    main()
